        url = (
            "https://raw.githubusercontent.com/example/project/"
            f"{COMMIT_SHA}/owner-profile.public.json"
        )
        with self.assertRaises(moltbook_publish.PublishError):
            moltbook_publish.safe_profile_url(url)

